<?php require_once __DIR__.'/../includes/admin-auth.php';require_admin(['super_admin','event_admin']);$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$ev=$s->fetch();if(!$ev){flash('danger','Event not found.');redirect('events.php');}$s=$pdo->prepare("SELECT r.registration_code,r.entry_code,r.created_at,r.status,u.name,u.email,u.mobile,c.checked_in_at FROM registrations r JOIN users u ON u.id=r.user_id LEFT JOIN checkins c ON c.registration_id=r.id WHERE r.event_id=? ORDER BY r.created_at DESC");$s->execute([$id]);$regs=$s->fetchAll();$pageTitle='Event details';require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel mb-4"><div class="d-flex justify-content-between flex-wrap gap-3"><div><span class="category-pill"><?=e($ev['category'])?></span><h2 class="mt-3"><?=e($ev['title'])?></h2><p class="muted"><?=e($ev['venue'])?> · <?=e(date('M j, Y',strtotime($ev['event_date'])))?></p><p><?=e($ev['description'])?></p></div><a class="btn btn-outline-primary align-self-start" href="edit-event.php?id=<?=$id?>">Edit event</a></div><div class="row g-3"><div class="col-md-3"><div class="stat-card"><div class="stat-value"><?=count($regs)?></div><div class="muted">Registrations</div></div></div><div class="col-md-3"><div class="stat-card"><div class="stat-value"><?=e($ev['capacity'])?></div><div class="muted">Capacity</div></div></div></div></div><div class="panel"><h2 class="h5 mb-3">Participants for this event</h2><div class="table-responsive"><table class="table"><thead><tr><th>Participant</th><th>Email</th><th>Registration ID</th><th>Attendance</th></tr></thead><tbody><?php foreach($regs as $r): ?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['registration_code'])?></td><td><span class="status-pill <?=$r['checked_in_at']?'status-checked':'status-pending'?>"><?=$r['checked_in_at']?'Checked in':'Not checked in'?></span></td></tr><?php endforeach; ?><?php if(!$regs): ?><tr><td colspan="4" class="text-center muted">No registrations yet.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
